// ISC 12 Mathematics ch13 Vector Algebra — practice bank with independent re-solve checks.
// Givens are shared constants; every authored answer (option vectors, values, model-answer vectors) is typed as a
// literal and the check recomputes it from the givens with ./vec.mjs (floating point, compared with a tolerance).
// Every set-up is SOYL's own (D-036); none repeats the CBSE 12 ch10 bank. Proofs of geometrical theorems by vectors
// are on the ISC removed list and are not asked.
import { Q, mk } from '../../isc-12-mathematics-ch01/src/lib.mjs';
import { add, sub, scl, dot, cross, mag, unit, cosAngle, angle, deg, proj, sectionIn, sectionEx, triArea, isZero, collinear, eqV, near, vt, pt } from './vec.mjs';
/** String.raw, except that a backslash-n not followed by a lower-case letter becomes a newline. */
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
const V = (a) => `$${vt(a)}$`;
const s2 = Math.SQRT2, s3 = Math.sqrt(3);

// =============================================================== MCQ — t01 magnitude, direction cosines, types
const kite = [2, -6, 3];
Q('m01', mk.mcq({ stem: r`The taut string of a kite runs from Aarav's hand to the kite along $${vt(kite)}$ (in metres). How long is the string?`, opts: ['$7$ m', '$49$ m', r`$\sqrt{13}$ m`, '$11$ m'], key: 'a', sol: r`$|\vec{a}| = \sqrt{2^2 + (-6)^2 + 3^2} = \sqrt{4 + 36 + 9} = \sqrt{49} = 7$. The value $49$ forgets the square root and $11$ adds the components without squaring.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => C.which([7, 49, Math.sqrt(13), 11], mag(kite)));
const m02v = [6, -2, 3];
const m02o = [[6 / 7, -2 / 7, 3 / 7], [6, -2, 3], [6 / 11, -2 / 11, 3 / 11], [-6 / 7, 2 / 7, -3 / 7]];
Q('m02', mk.mcq({ stem: r`A survey drone climbs along $${vt(m02v)}$. The direction cosines of its path are`, opts: [r`$\tfrac67, -\tfrac27, \tfrac37$`, '$6, -2, 3$', r`$\tfrac{6}{11}, -\tfrac{2}{11}, \tfrac{3}{11}$`, r`$-\tfrac67, \tfrac27, -\tfrac37$`], key: 'a', sol: r`$|\vec{v}| = \sqrt{36 + 4 + 9} = 7$, so $l, m, n = \tfrac67, -\tfrac27, \tfrac37$. The numbers $6, -2, 3$ are only direction ratios, and the last option points the opposite way.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which(m02o, unit(m02v)));
const m03v = [4, 4, -7];
const m03o = [[4 / 9, 4 / 9, -7 / 9], [4 / 81, 4 / 81, -7 / 81], [4 / 3, 4 / 3, -7 / 3], [4 / 9, 4 / 9, 7 / 9]];
Q('m03', mk.mcq({ stem: r`A guide rope on a tent in Ladakh points along $${vt(m03v)}$. The unit vector along the rope is`, opts: [r`$\tfrac19(4\hat{i} + 4\hat{j} - 7\hat{k})$`, r`$\tfrac{1}{81}(4\hat{i} + 4\hat{j} - 7\hat{k})$`, r`$\tfrac13(4\hat{i} + 4\hat{j} - 7\hat{k})$`, r`$\tfrac19(4\hat{i} + 4\hat{j} + 7\hat{k})$`], key: 'a', sol: r`$|\vec{v}| = \sqrt{16 + 16 + 49} = \sqrt{81} = 9$, so $\hat{v} = \dfrac{\vec{v}}{9}$. Dividing by $81$ uses the square of the magnitude instead of the magnitude.`, d: 1, c: 'understanding', t: [1], time: 50 }), (C) => C.which(m03o, unit(m03v)));
const f1 = [3, -1, 0], f2 = [-6, 2, 0];
Q('m04', mk.mcq({ stem: r`Two ropes pull a crate across a godown floor with forces $${vt(f1)}$ and $${vt(f2)}$. These two vectors are`, opts: ['collinear and opposite in direction', 'equal vectors', 'perpendicular to each other', 'neither collinear nor perpendicular'], key: 'a', sol: r`$-6\hat{i} + 2\hat{j} = -2(3\hat{i} - \hat{j})$: a negative multiple, so the forces act along the same line in opposite directions. They are not equal (different magnitudes and directions), and their dot product $-18 - 2 = -20 \ne 0$.`, d: 2, c: 'understanding', t: [1], time: 50 }), (C) => C.which([collinear(f1, f2) && dot(f1, f2) < 0, eqV(f1, f2), near(dot(f1, f2), 0), !collinear(f1, f2) && !near(dot(f1, f2), 0)], true));
Q('m05', mk.mcq({ stem: r`A support beam in a planetarium dome makes equal acute angles with the $x$-, $y$- and $z$-axes. Each of its direction cosines equals`, opts: [r`$\dfrac{1}{\sqrt{3}}$`, r`$\dfrac13$`, r`$\sqrt{3}$`, r`$\dfrac{1}{\sqrt{2}}$`], key: 'a', sol: r`With $l = m = n$ and $l^2 + m^2 + n^2 = 1$, we get $3l^2 = 1$, so $l = \dfrac{1}{\sqrt{3}}$ (positive, since the angles are acute).`, d: 2, c: 'application', t: [1], time: 60 }), (C) => C.which([1 / s3, 1 / 3, s3, 1 / s2], Math.sqrt(1 / 3)));
const m06v = [1, 1, s2];
Q('m06', mk.mcq({ stem: r`The pointer of a sundial model leans along $\hat{i} + \hat{j} + \sqrt{2}\,\hat{k}$. The angle it makes with the $x$-axis is`, opts: [r`$60^\circ$`, r`$45^\circ$`, r`$30^\circ$`, r`$90^\circ$`], key: 'a', sol: r`$|\vec{v}| = \sqrt{1 + 1 + 2} = 2$, so $l = \cos\alpha = \tfrac12$ and $\alpha = 60^\circ$. The angle with the $z$-axis, where $\cos\gamma = \tfrac{\sqrt{2}}{2}$, is the $45^\circ$.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => C.which([60, 45, 30, 90], deg(Math.acos(m06v[0] / mag(m06v)))));

// =============================================================== MCQ — t02 position vectors and operations
const P07 = [2, -1, 4], Q07 = [5, 3, -2];
const m07o = [[3, 4, -6], [-3, -4, 6], [7, 2, 2], [3, 2, 2]];
Q('m07', mk.mcq({ stem: r`A drone flies straight from the point $P${pt(P07)}$ to the point $Q${pt(Q07)}$. The vector $\overrightarrow{PQ}$ is`, opts: m07o.map(V), key: 'a', sol: r`$\overrightarrow{PQ}$ = position vector of $Q$ minus that of $P$ ("head minus tail") $= (5 - 2)\hat{i} + (3 + 1)\hat{j} + (-2 - 4)\hat{k}$. The second option is $\overrightarrow{QP}$ and the third adds the position vectors.`, d: 1, c: 'understanding', t: [2], time: 50 }), (C) => C.which(m07o, sub(Q07, P07)));
const a08 = [1, 2, -1], b08 = [2, -1, 0];
const m08o = [[-4, 7, -2], [8, 1, -2], [-4, 1, -2], [4, -7, 2]];
Q('m08', mk.mcq({ stem: r`In a game engine, $\vec{a} = ${vt(a08)}$ and $\vec{b} = ${vt(b08)}$. The vector $2\vec{a} - 3\vec{b}$ is`, opts: m08o.map(V), key: 'a', sol: r`$2\vec{a} = 2\hat{i} + 4\hat{j} - 2\hat{k}$ and $3\vec{b} = 6\hat{i} - 3\hat{j}$, so $2\vec{a} - 3\vec{b} = -4\hat{i} + 7\hat{j} - 2\hat{k}$.`, d: 1, c: 'understanding', t: [2], time: 50 }), (C) => C.which(m08o, sub(scl(2, a08), scl(3, b08))));
const a09 = [2, 1, -2], b09 = [1, -3, 5];
Q('m09', mk.mcq({ stem: r`Two successive gusts move a balloon through $${vt(a09)}$ and then $${vt(b09)}$ (in km). Its total displacement has magnitude`, opts: [r`$\sqrt{22}$ km`, r`$3 + \sqrt{35}$ km`, r`$\sqrt{38}$ km`, '$22$ km'], key: 'a', sol: r`The resultant is $3\hat{i} - 2\hat{j} + 3\hat{k}$, of magnitude $\sqrt{9 + 4 + 9} = \sqrt{22}$. Adding the two magnitudes $3 + \sqrt{35}$ ignores the directions.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => C.which([Math.sqrt(22), 3 + Math.sqrt(35), Math.sqrt(38), 22], mag(add(a09, b09))));
const m10 = (l) => [l, 6, -3];
Q('m10', mk.mcq({ stem: r`For which value of $\lambda$ is the cable direction $\lambda\hat{i} + 6\hat{j} - 3\hat{k}$ parallel to the pole direction $2\hat{i} + 4\hat{j} - 2\hat{k}$?`, opts: ['$3$', '$4$', '$-3$', '$1$'], key: 'a', sol: r`Parallel vectors have proportional components: $\dfrac{\lambda}{2} = \dfrac{6}{4} = \dfrac{-3}{-2} = \dfrac32$, so $\lambda = 3$.`, d: 2, c: 'understanding', t: [1, 2], time: 60 }), (C) => C.which([3, 4, -3, 1].map((l) => collinear(m10(l), [2, 4, -2])), true));

// =============================================================== MCQ — t03 section formula
const A11 = [3, -2, 5], B11 = [-1, 4, 1];
const m11o = [[1, 1, 3], [2, 2, 6], [-2, 3, -2], [4, -6, 4]];
Q('m11', mk.mcq({ stem: r`A footbridge in Shillong runs between pillars at $A${pt(A11)}$ and $B${pt(B11)}$. A lamp is fixed at its midpoint. The position vector of the lamp is`, opts: m11o.map(V), key: 'a', sol: r`Midpoint: $\dfrac{\vec{a} + \vec{b}}{2} = \dfrac{2\hat{i} + 2\hat{j} + 6\hat{k}}{2} = \hat{i} + \hat{j} + 3\hat{k}$. The second option forgets to halve; the third is half of $\vec{b} - \vec{a}$.`, d: 1, c: 'understanding', t: [3], time: 50 }), (C) => C.which(m11o, sectionIn(A11, B11, 1, 1)));
const P12 = [1, -2, 3], Q12 = [6, 8, -2];
const m12o = [[3, 2, 1], [4, 6, 0], [-9, -22, 13], [2, 0, 2]];
Q('m12', mk.mcq({ stem: r`On a straight pipeline from $P${pt(P12)}$ to $Q${pt(Q12)}$, a valve divides $PQ$ internally in the ratio $2 : 3$. The valve is at`, opts: m12o.map((v) => `$${pt(v)}$`), key: 'a', sol: r`$\vec{r} = \dfrac{2\vec{q} + 3\vec{p}}{5} = \dfrac{(12 + 3,\ 16 - 6,\ -4 + 9)}{5} = (3, 2, 1)$. Swapping the weights gives $(4, 6, 0)$, which divides $PQ$ in $3 : 2$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => C.which(m12o, sectionIn(P12, Q12, 2, 3)));
const P13 = [2, 1, 0], Q13 = [4, 5, 2];
const m13o = [[5, 7, 3], [3.5, 4, 1.5], [1, -1, -1], [10, 14, 6]];
Q('m13', mk.mcq({ stem: r`A survey peg is placed on line $PQ$ produced beyond $Q$, dividing $PQ$ externally in the ratio $3 : 1$, where $P = ${pt(P13)}$ and $Q = ${pt(Q13)}$. The peg is at`, opts: m13o.map((v) => `$${pt(v)}$`), key: 'a', sol: r`External division: $\vec{r} = \dfrac{3\vec{q} - \vec{p}}{3 - 1} = \dfrac{(12 - 2,\ 15 - 1,\ 6 - 0)}{2} = (5, 7, 3)$. The point $(3.5, 4, 1.5)$ divides $PQ$ internally in $3 : 1$; forgetting to divide by $2$ gives $(10, 14, 6)$.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => C.which(m13o, sectionEx(P13, Q13, 3, 1)));
const P14 = [2, 1, -1], Q14 = [8, 7, 5], R14 = [6, 5, 3];
Q('m14', mk.mcq({ stem: r`A climbing wall has holds at $P${pt(P14)}$, $R${pt(R14)}$ and $Q${pt(Q14)}$, all on one straight line. In what ratio does $R$ divide $PQ$?`, opts: ['$2 : 1$ internally', '$1 : 2$ internally', '$2 : 1$ externally', '$3 : 1$ internally'], key: 'a', sol: r`$\overrightarrow{PR} = 4\hat{i} + 4\hat{j} + 4\hat{k}$ and $\overrightarrow{RQ} = 2\hat{i} + 2\hat{j} + 2\hat{k}$, so $\overrightarrow{PR} = 2\,\overrightarrow{RQ}$: $R$ lies between $P$ and $Q$ with $PR : RQ = 2 : 1$.`, d: 3, c: 'analysis', t: [3], time: 75 }), (C) => C.which([eqV(sectionIn(P14, Q14, 2, 1), R14), eqV(sectionIn(P14, Q14, 1, 2), R14), eqV(sectionEx(P14, Q14, 2, 1), R14), eqV(sectionIn(P14, Q14, 3, 1), R14)], true));

// =============================================================== MCQ — t04 scalar product and projections
const a15 = [3, -2, 4], b15 = [1, 5, 2];
Q('m15', mk.mcq({ stem: r`A fitness app stores the vectors $${vt(a15)}$ and $${vt(b15)}$. Their scalar product is`, opts: ['$1$', '$21$', r`$3\hat{i} - 10\hat{j} + 8\hat{k}$`, '$-1$'], key: 'a', sol: r`$\vec{a} \cdot \vec{b} = 3(1) + (-2)(5) + 4(2) = 3 - 10 + 8 = 1$. A scalar product is a number, not a vector.`, d: 1, c: 'understanding', t: [4], time: 45 }), (C) => C.which([1, 21, NaN, -1], dot(a15, b15)));
const a16 = [1, 2, 2], b16 = [2, -1, 2];
Q('m16', mk.mcq({ stem: r`Two struts of a roof truss point along $${vt(a16)}$ and $${vt(b16)}$. The cosine of the angle between them is`, opts: [r`$\dfrac49$`, r`$-\dfrac49$`, r`$\dfrac43$`, r`$\dfrac23$`], key: 'a', sol: r`$\vec{a} \cdot \vec{b} = 2 - 2 + 4 = 4$ and $|\vec{a}| = |\vec{b}| = 3$, so $\cos\theta = \dfrac{4}{3 \times 3} = \dfrac49$.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => C.which([4 / 9, -4 / 9, 4 / 3, 2 / 3], cosAngle(a16, b16)));
const m17 = (l) => [2, l, 1];
Q('m17', mk.mcq({ stem: r`A laser beam along $2\hat{i} + \lambda\hat{j} + \hat{k}$ must hit a mirror normal $3\hat{i} - 2\hat{j} + 4\hat{k}$ at right angles. Then $\lambda =$`, opts: ['$5$', '$-5$', '$2$', '$-2$'], key: 'a', sol: r`Perpendicular means the dot product is $0$: $6 - 2\lambda + 4 = 0$, so $\lambda = 5$.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => C.which([5, -5, 2, -2].map((l) => near(dot(m17(l), [3, -2, 4]), 0)), true));
const a18 = [4, -1, 8], b18 = [2, 1, -2];
Q('m18', mk.mcq({ stem: r`In a physics simulation, the scalar projection of $\vec{a} = ${vt(a18)}$ on $\vec{b} = ${vt(b18)}$ is`, opts: ['$-3$', '$3$', '$-9$', r`$-\dfrac{1}{3}$`], key: 'a', sol: r`$\vec{a} \cdot \vec{b} = 8 - 1 - 16 = -9$ and $|\vec{b}| = 3$, so the projection is $\dfrac{-9}{3} = -3$. The negative sign shows the angle between them is obtuse.`, d: 2, c: 'application', t: [4], time: 60 }), (C) => C.which([-3, 3, -9, -1 / 3], proj(a18, b18)));
Q('m19', mk.mcq({ stem: r`Two forces have magnitudes $|\vec{a}| = 4$ and $|\vec{b}| = 3$ newtons, and $\vec{a} \cdot \vec{b} = -2$. The magnitude of their resultant $\vec{a} + \vec{b}$ is`, opts: [r`$\sqrt{21}$`, r`$\sqrt{29}$`, '$7$', '$5$'], key: 'a', sol: r`$|\vec{a} + \vec{b}|^2 = |\vec{a}|^2 + |\vec{b}|^2 + 2\,\vec{a} \cdot \vec{b} = 16 + 9 - 4 = 21$, so the resultant is $\sqrt{21}$ N. Ignoring the dot-product term gives $5$.`, d: 3, c: 'application', t: [4], time: 75 }), (C) => { const a = [4, 0, 0], th = Math.acos(-2 / 12), b = [3 * Math.cos(th), 3 * Math.sin(th), 0]; C.assert(near(dot(a, b), -2), 'sample vectors'); C.which([Math.sqrt(21), Math.sqrt(29), 7, 5], mag(add(a, b))); });
const a20 = [3, 1, -1], b20 = [1, 2, 2];
const m20o = [[1 / 3, 2 / 3, 2 / 3], [1, 2, 2], [1 / 9, 2 / 9, 2 / 9], [1, 1 / 3, -1 / 3]];
Q('m20', mk.mcq({ stem: r`A robot's step $\vec{a} = ${vt(a20)}$ is split along the corridor direction $\vec{b} = ${vt(b20)}$. The vector projection of $\vec{a}$ on $\vec{b}$ is`, opts: [r`$\tfrac13(\hat{i} + 2\hat{j} + 2\hat{k})$`, r`$\hat{i} + 2\hat{j} + 2\hat{k}$`, r`$\tfrac19(\hat{i} + 2\hat{j} + 2\hat{k})$`, r`$\tfrac13(3\hat{i} + \hat{j} - \hat{k})$`], key: 'a', sol: r`$\vec{a} \cdot \vec{b} = 3 + 2 - 2 = 3$ and $|\vec{b}|^2 = 9$, so the vector projection is $\dfrac{\vec{a} \cdot \vec{b}}{|\vec{b}|^2}\,\vec{b} = \dfrac39\,\vec{b} = \tfrac13(\hat{i} + 2\hat{j} + 2\hat{k})$.`, d: 3, c: 'application', t: [4], time: 75 }), (C) => C.which(m20o, scl(dot(a20, b20) / dot(b20, b20), b20)));
Q('m27', mk.mcq({ stem: r`For two non-zero vectors drawn from one corner of a plot of land, $|\vec{a} + \vec{b}| = |\vec{a} - \vec{b}|$. What does this tell you?`, opts: [r`$\vec{a}$ and $\vec{b}$ are perpendicular`, r`$\vec{a}$ and $\vec{b}$ are parallel`, r`$|\vec{a}| = |\vec{b}|$`, r`$\vec{a} = \vec{b}$`], key: 'a', sol: r`Squaring: $|\vec{a}|^2 + |\vec{b}|^2 + 2\,\vec{a} \cdot \vec{b} = |\vec{a}|^2 + |\vec{b}|^2 - 2\,\vec{a} \cdot \vec{b}$, so $4\,\vec{a} \cdot \vec{b} = 0$: the vectors are perpendicular (the parallelogram on them is a rectangle with equal diagonals).`, d: 3, c: 'analysis', t: [4], time: 75 }), (C) => { const a = [3, 0, 0], b = [0, 5, 0], c = [3, 4, 0]; C.assert(near(mag(add(a, b)), mag(sub(a, b))) && !near(mag(add(a, c)), mag(sub(a, c))), 'perpendicular iff equal diagonals'); C.key('a'); });

// =============================================================== MCQ — t05 vector product, areas, collinearity
const a21 = [1, 2, 0], b21 = [0, 1, 3];
const m21o = [[6, -3, 1], [-6, 3, -1], [6, 3, 1], [0, 2, 0]];
Q('m21', mk.mcq({ stem: r`A torque calculation in a workshop needs $\vec{a} \times \vec{b}$ for $\vec{a} = ${vt(a21)}$ and $\vec{b} = ${vt(b21)}$. It equals`, opts: m21o.map(V), key: 'a', sol: r`$\vec{a} \times \vec{b} = \begin{vmatrix} \hat{i} & \hat{j} & \hat{k} \\ 1 & 2 & 0 \\ 0 & 1 & 3 \end{vmatrix} = (6 - 0)\hat{i} - (3 - 0)\hat{j} + (1 - 0)\hat{k}$. The second option is $\vec{b} \times \vec{a}$.`, d: 2, c: 'understanding', t: [5], time: 60 }), (C) => C.which(m21o, cross(a21, b21)));
const a22 = [2, 1, 2], b22 = [1, 0, -1];
Q('m22', mk.mcq({ stem: r`A solar panel is a parallelogram with adjacent edges $${vt(a22)}$ and $${vt(b22)}$ (in metres). Its area is`, opts: [r`$3\sqrt{2}$ m²`, r`$\dfrac{3\sqrt{2}}{2}$ m²`, '$18$ m²', r`$\sqrt{6}$ m²`], key: 'a', sol: r`$\vec{a} \times \vec{b} = -\hat{i} + 4\hat{j} - \hat{k}$, of magnitude $\sqrt{1 + 16 + 1} = \sqrt{18} = 3\sqrt{2}$. Halving gives the area of the triangle, not the parallelogram.`, d: 2, c: 'application', t: [5], time: 75 }), (C) => C.which([3 * s2, 3 * s2 / 2, 18, Math.sqrt(6)], mag(cross(a22, b22))));
const A23 = [1, 0, 0], B23 = [0, 2, 0], C23 = [0, 0, 3];
Q('m23', mk.mcq({ stem: r`A triangular sail is tied at $A${pt(A23)}$, $B${pt(B23)}$ and $C${pt(C23)}$. Its area in square units is`, opts: [r`$\dfrac72$`, '$7$', r`$\dfrac{\sqrt{14}}{2}$`, '$3$'], key: 'a', sol: r`$\overrightarrow{AB} \times \overrightarrow{AC} = (-\hat{i} + 2\hat{j}) \times (-\hat{i} + 3\hat{k}) = 6\hat{i} + 3\hat{j} + 2\hat{k}$, of magnitude $\sqrt{36 + 9 + 4} = 7$; the area is half of this, $\dfrac72$.`, d: 3, c: 'application', t: [5], time: 90 }), (C) => C.which([3.5, 7, Math.sqrt(14) / 2, 3], triArea(A23, B23, C23)));
Q('m24', mk.mcq({ stem: r`A spanner applies forces where $|\vec{a}| = 6$, $|\vec{b}| = 5$ and $\vec{a} \cdot \vec{b} = 18$. Then $|\vec{a} \times \vec{b}| =$`, opts: ['$24$', '$18$', '$30$', '$12$'], key: 'a', sol: r`$\cos\theta = \dfrac{18}{30} = \dfrac35$, so $\sin\theta = \dfrac45$ and $|\vec{a} \times \vec{b}| = 6 \times 5 \times \dfrac45 = 24$. (Check: $24^2 + 18^2 = 900 = (6 \times 5)^2$.)`, d: 3, c: 'application', t: [4, 5], time: 75 }), (C) => { const th = Math.acos(18 / 30), a = [6, 0, 0], b = [5 * Math.cos(th), 5 * Math.sin(th), 0]; C.which([24, 18, 30, 12], mag(cross(a, b))); });
const a25 = [1, 1, 0], b25 = [0, 1, 1];
const m25o = [[1 / s3, -1 / s3, 1 / s3], [1, -1, 1], [1 / s3, 1 / s3, 1 / s3], [1 / s2, 0, 1 / s2]];
Q('m25', mk.mcq({ stem: r`A drone camera must point at right angles to both edges $${vt(a25)}$ and $${vt(b25)}$ of a rooftop. A unit vector it could point along is`, opts: [r`$\dfrac{1}{\sqrt{3}}(\hat{i} - \hat{j} + \hat{k})$`, r`$\hat{i} - \hat{j} + \hat{k}$`, r`$\dfrac{1}{\sqrt{3}}(\hat{i} + \hat{j} + \hat{k})$`, r`$\dfrac{1}{\sqrt{2}}(\hat{i} + \hat{k})$`], key: 'a', sol: r`$\vec{a} \times \vec{b} = \hat{i} - \hat{j} + \hat{k}$, perpendicular to both; dividing by its magnitude $\sqrt{3}$ makes it a unit vector. The second option is perpendicular but not a unit vector.`, d: 2, c: 'understanding', t: [5], time: 75 }), (C) => C.which(m25o, unit(cross(a25, b25))));
const m26 = (k) => [[1, 2, 3], [3, 5, 4], [7, 11, k]];
Q('m26', mk.mcq({ stem: r`Three marker buoys at $A(1, 2, 3)$, $B(3, 5, 4)$ and $C(7, 11, k)$ must lie on one straight line. Then $k =$`, opts: ['$6$', '$5$', '$7$', '$3$'], key: 'a', sol: r`$\overrightarrow{AB} = 2\hat{i} + 3\hat{j} + \hat{k}$ and $\overrightarrow{AC} = 6\hat{i} + 9\hat{j} + (k - 3)\hat{k}$. Collinear means $\overrightarrow{AB} \times \overrightarrow{AC} = \vec{0}$, i.e. $\overrightarrow{AC} = 3\,\overrightarrow{AB}$, so $k - 3 = 3$ and $k = 6$.`, d: 3, c: 'application', t: [5], time: 75 }), (C) => C.which([6, 5, 7, 3].map((k) => { const [A, B, Cc] = m26(k); return collinear(sub(B, A), sub(Cc, A)); }), true));
const jxi = cross([0, 1, 0], [1, 0, 0]);
Q('m28', mk.mcq({ stem: r`Using the cyclic order of the unit vectors along the axes, the cross product $\hat{j} \times \hat{i}$ equals`, opts: [r`$-\hat{k}$`, r`$\hat{k}$`, r`$\vec{0}$`, '$1$'], key: 'a', sol: r`$\hat{i} \times \hat{j} = \hat{k}$, and swapping the order changes the sign: $\hat{j} \times \hat{i} = -\hat{k}$. The answer is a vector, so $1$ is impossible.`, d: 1, c: 'recall', t: [5], time: 30 }), (C) => { C.assert(eqV(jxi, [0, 0, -1]), 'j x i = -k'); C.key('a'); });

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`The numbers $\tfrac12, \tfrac12, \tfrac12$ can be the direction cosines of a line.`, r: r`The direction cosines $l, m, n$ of any line satisfy $l^2 + m^2 + n^2 = 1$.`, key: 'd', sol: r`R is true. Here $\tfrac14 + \tfrac14 + \tfrac14 = \tfrac34 \ne 1$, so A is false.`, d: 2, c: 'analysis', t: [1] }), (C) => { C.assert(!near(3 * 0.25, 1) && near(dot(unit([2, -3, 6]), unit([2, -3, 6])), 1), 'A false, R true'); C.key('d'); });
Q('ar2', mk.ar({ a: r`If $\hat{a}$ and $\hat{b}$ are unit vectors with $\hat{a} \cdot \hat{b} = 0$, then $|\hat{a} + \hat{b}| = \sqrt{2}$.`, r: r`$|\vec{a} + \vec{b}|^2 = |\vec{a}|^2 + |\vec{b}|^2 + 2\,\vec{a} \cdot \vec{b}$ for any vectors.`, key: 'a', sol: r`By R, $|\hat{a} + \hat{b}|^2 = 1 + 1 + 0 = 2$, which gives A. Both are true and R explains A.`, d: 2, c: 'understanding', t: [4] }), (C) => { const a = unit([1, 2, 2]), b = unit([2, 1, -2]); C.assert(near(dot(a, b), 0) && near(mag(add(a, b)), s2), 'sqrt 2'); C.key('a'); });
Q('ar3', mk.ar({ a: r`$(2\hat{i} + \hat{j}) \times (4\hat{i} + 2\hat{j}) = \vec{0}$.`, r: 'The vector product of two collinear vectors is the zero vector.', key: 'a', sol: r`$4\hat{i} + 2\hat{j} = 2(2\hat{i} + \hat{j})$, so the vectors are collinear and, by R, their cross product is $\vec{0}$ (the angle between them is $0$, and $\sin 0 = 0$). Both are true and R explains A.`, d: 2, c: 'understanding', t: [5] }), (C) => { C.assert(isZero(cross([2, 1, 0], [4, 2, 0])), 'zero'); C.key('a'); });
Q('ar4', mk.ar({ a: r`$\vec{a} \cdot \vec{b} = \vec{b} \cdot \vec{a}$ for all vectors $\vec{a}$ and $\vec{b}$.`, r: r`$\vec{a} \times \vec{b} = \vec{b} \times \vec{a}$ for all vectors $\vec{a}$ and $\vec{b}$.`, key: 'c', sol: r`The scalar product is commutative, so A is true. R is false: $\vec{b} \times \vec{a} = -(\vec{a} \times \vec{b})$.`, d: 2, c: 'analysis', t: [4, 5] }), (C) => { const a = [1, 2, 3], b = [-2, 0, 5]; C.assert(near(dot(a, b), dot(b, a)) && eqV(cross(b, a), scl(-1, cross(a, b))) && !eqV(cross(a, b), cross(b, a)), 'A true, R false'); C.key('c'); });
Q('ar5', mk.ar({ a: r`No point divides a segment $AB$ externally in the ratio $1 : 1$.`, r: r`The external section formula $\dfrac{m\vec{b} - n\vec{a}}{m - n}$ has $m - n$ in its denominator.`, key: 'a', sol: r`With $m = n$ the denominator is $0$, so the formula breaks down: geometrically, a point outside $AB$ cannot be equally far from $A$ and $B$ while lying on the line. Both are true and R explains A.`, d: 3, c: 'analysis', t: [3] }), (C) => { const A = [0, 0, 0], B = [4, 0, 0]; C.assert(Number.isFinite(sectionEx(A, B, 3, 2)[0]) && !Number.isFinite(sectionEx(A, B, 1, 1)[0]), 'm = n undefined, m ≠ n fine'); C.key('a'); });
Q('ar6', mk.ar({ a: r`The position vector of the point $P(3, -4, 0)$ has magnitude $5$.`, r: r`The magnitude of $x\hat{i} + y\hat{j} + z\hat{k}$ is $x + y + z$.`, key: 'c', sol: r`$|3\hat{i} - 4\hat{j}| = \sqrt{9 + 16} = 5$, so A is true. R is false: the magnitude is $\sqrt{x^2 + y^2 + z^2}$ (here $x + y + z = -1$).`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(near(mag([3, -4, 0]), 5) && 3 - 4 + 0 !== 5, 'A true, R false'); C.key('c'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: r`A diver descends straight down through $-3\hat{k}$ metres. The unit vector giving the diver's direction of motion is $-\hat{k}$.`, key: 't', sol: r`$|-3\hat{k}| = 3$, and $\dfrac{-3\hat{k}}{3} = -\hat{k}$. True.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(eqV(unit([0, 0, -3]), [0, 0, -1]), 'unit'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`If $\vec{a} \cdot \vec{b} = 0$, then $\vec{a}$ or $\vec{b}$ must be the zero vector.`, key: 'f', sol: r`False. Non-zero perpendicular vectors also have zero dot product, for example $\hat{i} + \hat{j}$ and $\hat{i} - \hat{j}$.`, d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(near(dot([1, 1, 0], [1, -1, 0]), 0), 'counterexample'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`The vector $\vec{a} \times \vec{b}$ is perpendicular to both $\vec{a}$ and $\vec{b}$.`, key: 't', sol: r`True: by definition $\vec{a} \times \vec{b}$ is along the normal to the plane of $\vec{a}$ and $\vec{b}$, so its dot product with each of them is $0$.`, d: 1, c: 'recall', t: [5] }), (C) => { const a = [2, -1, 3], b = [1, 4, -2], c = cross(a, b); C.assert(near(dot(c, a), 0) && near(dot(c, b), 0), 'perpendicular'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`The point that divides $AB$ externally in the ratio $2 : 1$ lies between $A$ and $B$.`, key: 'f', sol: r`False. External division puts the point on $AB$ produced: in $2 : 1$ it lies beyond $B$, with $B$ the midpoint of $A$ and the new point.`, d: 2, c: 'understanding', t: [3] }), (C) => { const A = [0, 0, 0], B = [3, 0, 0], P = sectionEx(A, B, 2, 1); C.assert(P[0] > 3 && near((A[0] + P[0]) / 2, B[0]), 'beyond B, B midpoint'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`A robot arm reaches from its base to its tip along $3\hat{i} - 6\hat{j} + 2\hat{k}$. The arm is ____ units long.`, acc: [['7', '$7$']], sol: r`$\sqrt{9 + 36 + 4} = \sqrt{49} = 7$.`, d: 1, c: 'understanding', t: [1] }), (C) => C.blank(mag([3, -6, 2])));
Q('fb2', mk.fill({ stem: r`If a velocity vector $\vec{v}$ has magnitude $7$, then $\vec{v} \cdot \vec{v} =$ ____.`, acc: [['49', '$49$']], sol: r`$\vec{v} \cdot \vec{v} = |\vec{v}|^2 = 49$.`, d: 1, c: 'understanding', t: [4] }), (C) => C.blank(dot([2, 3, 6], [2, 3, 6])));
Q('fb3', mk.fill({ stem: r`Completing the cyclic rule for the axis unit vectors: $\hat{i} \times \hat{j} = $ ____ (write the unit vector).`, acc: [['k', 'k̂']], sol: r`In the cyclic order $\hat{i} \to \hat{j} \to \hat{k}$, $\hat{i} \times \hat{j} = \hat{k}$ (written k).`, d: 1, c: 'recall', t: [5] }), (C) => { C.assert(eqV(cross([1, 0, 0], [0, 1, 0]), [0, 0, 1]), 'i x j = k'); C.blank('k'); });

// =============================================================== numerical
Q('n01', mk.num({ stem: r`A wind-sock points along $\vec{a} = \hat{i} - 2\hat{j} + 2\hat{k}$. For which positive number $k$ does $k\vec{a}$ have magnitude $12$?`, value: 4, sol: r`$|\vec{a}| = \sqrt{1 + 4 + 4} = 3$ and $|k\vec{a}| = 3k = 12$, so $k = 4$.`, scheme: [['4', 1]], d: 1, c: 'understanding', t: [1], time: 60 }), (C) => C.val(12 / mag([1, -2, 2])));
const P_n2 = [1, 2, -1], Q_n2 = [3, -4, 2];
Q('n02', mk.num({ stem: r`Two mobile towers stand at $P${pt(P_n2)}$ and $Q${pt(Q_n2)}$ (in km). Find the straight-line distance between them in km.`, value: 7, sol: r`$\overrightarrow{PQ} = 2\hat{i} - 6\hat{j} + 3\hat{k}$, so $PQ = \sqrt{4 + 36 + 9} = 7$ km.`, scheme: [['7', 1]], d: 1, c: 'understanding', t: [2], time: 60 }), (C) => C.val(mag(sub(Q_n2, P_n2))));
const G_A = [1, 2, 3], G_B = [4, -1, 0], G_C = [-2, 5, 6];
const G = scl(1 / 3, add(add(G_A, G_B), G_C));
Q('n03', mk.num({ stem: r`A triangular park has corners $A${pt(G_A)}$, $B${pt(G_B)}$ and $C${pt(G_C)}$. A fountain is at the centroid $G$, whose position vector is $\tfrac13(\vec{a} + \vec{b} + \vec{c})$. Find the sum of the coordinates of $G$.`, value: 6, sol: r`$\vec{a} + \vec{b} + \vec{c} = 3\hat{i} + 6\hat{j} + 9\hat{k}$, so $G = (1, 2, 3)$ and the sum is $1 + 2 + 3 = 6$.`, scheme: [['6', 1]], d: 2, c: 'application', t: [3], time: 90 }), (C) => { C.assert(eqV(G, [1, 2, 3]), 'G'); C.val(G[0] + G[1] + G[2]); });
const a_n4 = [0, 3, 3], b_n4 = [3, 0, 3];
Q('n04', mk.num({ stem: r`Two roof rafters point along $${vt(a_n4)}$ and $${vt(b_n4)}$. Find the angle between them in degrees.`, value: 60, unit: '°', sol: r`$\vec{a} \cdot \vec{b} = 9$ and $|\vec{a}| = |\vec{b}| = 3\sqrt{2}$, so $\cos\theta = \dfrac{9}{18} = \dfrac12$ and $\theta = 60^\circ$.`, scheme: [['60', 1]], d: 2, c: 'application', t: [4], time: 75 }), (C) => C.val(deg(angle(a_n4, b_n4)), 1e-6));
const F_n5 = [4, -1, 2], S_n5 = [1, 2, 0], E_n5 = [3, 5, 4];
Q('n05', mk.num({ stem: r`A constant force $\vec{F} = ${vt(F_n5)}$ newtons pushes a trolley from the point $${pt(S_n5)}$ to the point $${pt(E_n5)}$ (in metres). The work done is $\vec{F} \cdot \vec{d}$, where $\vec{d}$ is the displacement. Find the work in joules.`, value: 13, unit: 'J', sol: r`$\vec{d} = 2\hat{i} + 3\hat{j} + 4\hat{k}$, so $W = 8 - 3 + 8 = 13$ J.`, scheme: [['13', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => C.val(dot(F_n5, sub(E_n5, S_n5))));
const T_A = [1, 1, 1], T_B = [2, 3, 1], T_C = [3, 1, 3];
Q('n06', mk.num({ stem: r`A triangular glass pane has corners $A${pt(T_A)}$, $B${pt(T_B)}$ and $C${pt(T_C)}$ (in feet). Find its area in square feet.`, value: 3, sol: r`$\overrightarrow{AB} \times \overrightarrow{AC} = (\hat{i} + 2\hat{j}) \times (2\hat{i} + 2\hat{k}) = 4\hat{i} - 2\hat{j} - 4\hat{k}$, of magnitude $6$; the area is $\tfrac12 \times 6 = 3$.`, scheme: [['3', 1]], d: 2, c: 'application', t: [5], time: 90 }), (C) => C.val(triArea(T_A, T_B, T_C)));

// =============================================================== short answer, 2 marks
const s201v = [2, -3, 6];
Q('s201', mk.short({ marks: 2, stem: r`A zip-line cable runs along $\vec{a} = ${vt(s201v)}$. Find the unit vector along the cable and its direction cosines.`, model: r`$|\vec{a}| = \sqrt{4 + 9 + 36} = 7$, so $\hat{a} = \tfrac17(2\hat{i} - 3\hat{j} + 6\hat{k})$.\n\nThe direction cosines are $\tfrac27, -\tfrac37, \tfrac67$.`, sol: 'Divide by the magnitude; the components of the unit vector are the direction cosines.', scheme: [['Magnitude 7 and unit vector', 1], ['Direction cosines', 1]], d: 1, c: 'understanding', t: [1], time: 90 }), (C) => { C.assert(near(mag(s201v), 7), 'mag 7'); C.model([7, r`\tfrac27, -\tfrac37, \tfrac67`]); });
const P202 = [-1, 3, 2], Q202 = [4, 0, -2];
Q('s202', mk.short({ marks: 2, stem: r`A delivery drone hops from the depot $P${pt(P202)}$ to a rooftop $Q${pt(Q202)}$. Write $\overrightarrow{PQ}$ in component form and find the length of the hop.`, model: r`$\overrightarrow{PQ} = (4 + 1)\hat{i} + (0 - 3)\hat{j} + (-2 - 2)\hat{k} = 5\hat{i} - 3\hat{j} - 4\hat{k}$.\n\n$|\overrightarrow{PQ}| = \sqrt{25 + 9 + 16} = \sqrt{50} = 5\sqrt{2}$.`, sol: 'Head minus tail, then the magnitude.', scheme: [['PQ in components', 1], ['Length 5√2', 1]], d: 1, c: 'understanding', t: [2], time: 90 }), (C) => { const v = sub(Q202, P202); C.assert(eqV(v, [5, -3, -4]) && near(mag(v), 5 * s2), 'PQ'); C.model([vt(v), r`5\sqrt{2}`]); });
const s203v = [2, 1, -2];
Q('s203', mk.short({ marks: 2, stem: r`A ship must sail $9$ nautical miles in the direction of $${vt(s203v)}$. Write its displacement vector.`, model: r`$|${vt(s203v)}| = \sqrt{4 + 1 + 4} = 3$, so the unit vector is $\tfrac13(2\hat{i} + \hat{j} - 2\hat{k})$.\n\nDisplacement $= 9 \times \tfrac13(2\hat{i} + \hat{j} - 2\hat{k}) = 6\hat{i} + 3\hat{j} - 6\hat{k}$.`, sol: 'Magnitude times the unit vector.', scheme: [['Unit vector', 1], ['Vector of magnitude 9', 1]], d: 2, c: 'application', t: [1, 2], time: 90 }), (C) => { const d = scl(9, unit(s203v)); C.assert(eqV(d, [6, 3, -6]), 'displacement'); C.model([vt([6, 3, -6])]); });
const A204 = [4, 1, -2], B204 = [-2, 7, 4];
Q('s204', mk.short({ marks: 2, stem: r`A tunnel is dug from $A${pt(A204)}$ to $B${pt(B204)}$. A ventilation shaft is placed at the point dividing $AB$ internally in the ratio $1 : 2$. Find its position vector.`, model: r`$\vec{r} = \dfrac{1 \cdot \vec{b} + 2 \cdot \vec{a}}{1 + 2} = \dfrac{(-2 + 8)\hat{i} + (7 + 2)\hat{j} + (4 - 4)\hat{k}}{3} = 2\hat{i} + 3\hat{j}$.`, sol: 'r = (m b + n a)/(m + n) with m : n = 1 : 2.', scheme: [['Section formula with correct weights', 1], ['Position vector 2i + 3j', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { const R = sectionIn(A204, B204, 1, 2); C.assert(eqV(R, [2, 3, 0]), 'R'); C.model([vt([2, 3, 0])]); });
const A205 = [1, 2, -1], B205 = [3, 0, 1];
Q('s205', mk.short({ marks: 2, stem: r`A boundary wall from $A${pt(A205)}$ to $B${pt(B205)}$ is extended beyond $B$ to a gate $C$ that divides $AB$ externally in the ratio $3 : 2$. Find the position vector of the gate.`, model: r`$\vec{c} = \dfrac{3\vec{b} - 2\vec{a}}{3 - 2} = (9 - 2)\hat{i} + (0 - 4)\hat{j} + (3 + 2)\hat{k} = 7\hat{i} - 4\hat{j} + 5\hat{k}$.`, sol: 'External division: subtract the weighted vectors and divide by m − n.', scheme: [['External section formula', 1], ['7i − 4j + 5k', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { const R = sectionEx(A205, B205, 3, 2); C.assert(eqV(R, [7, -4, 5]), 'C'); C.model([vt([7, -4, 5])]); });
const s206 = (l) => [[l, 2, -1], [3, l, 4]];
Q('s206', mk.short({ marks: 2, stem: r`Two brackets on a frame point along $\lambda\hat{i} + 2\hat{j} - \hat{k}$ and $3\hat{i} + \lambda\hat{j} + 4\hat{k}$. Find $\lambda$ if the brackets are at right angles.`, model: r`Perpendicular, so the dot product is zero: $3\lambda + 2\lambda - 4 = 0$.\n\n$5\lambda = 4$, so $\lambda = \dfrac45$.`, sol: 'Set the scalar product to zero.', scheme: [['Dot product equation', 1], ['λ = 4/5', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => { const [u, v] = s206(0.8); C.assert(near(dot(u, v), 0), 'perpendicular at 4/5'); C.model([r`\dfrac45`]); });
const a207 = [2, 3, -1], b207 = [1, -2, 2];
Q('s207', mk.short({ marks: 2, stem: r`A slope-stability sensor resolves $\vec{a} = ${vt(a207)}$ along the hillside direction $\vec{b} = ${vt(b207)}$. Find the scalar projection of $\vec{a}$ on $\vec{b}$ and say what its sign means.`, model: r`$\vec{a} \cdot \vec{b} = 2 - 6 - 2 = -6$ and $|\vec{b}| = 3$, so the projection is $\dfrac{-6}{3} = -2$.\n\nThe negative sign means the angle between $\vec{a}$ and $\vec{b}$ is obtuse: $\vec{a}$ has a component of length $2$ opposite to $\vec{b}$.`, sol: 'a · b divided by |b|.', scheme: [['Dot product and |b|', 1], ['Projection −2 with meaning of sign', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => { C.assert(near(proj(a207, b207), -2), 'proj'); C.model([-2]); });
const a208 = [3, -1, 2], b208 = [1, 2, -1];
Q('s208', mk.short({ marks: 2, stem: r`For a lever on a bicycle crank, $\vec{a} = ${vt(a208)}$ and $\vec{b} = ${vt(b208)}$. Find $\vec{a} \times \vec{b}$ and its magnitude.`, model: r`$\vec{a} \times \vec{b} = \begin{vmatrix} \hat{i} & \hat{j} & \hat{k} \\ 3 & -1 & 2 \\ 1 & 2 & -1 \end{vmatrix} = (1 - 4)\hat{i} - (-3 - 2)\hat{j} + (6 + 1)\hat{k} = -3\hat{i} + 5\hat{j} + 7\hat{k}$.\n\n$|\vec{a} \times \vec{b}| = \sqrt{9 + 25 + 49} = \sqrt{83}$.`, sol: 'Expand the determinant along the first row.', scheme: [['Cross product', 1], ['Magnitude √83', 1]], d: 2, c: 'understanding', t: [5], time: 90 }), (C) => { const c = cross(a208, b208); C.assert(eqV(c, [-3, 5, 7]) && near(mag(c), Math.sqrt(83)), 'cross'); C.model([vt(c), r`\sqrt{83}`]); });
const d1_209 = [3, 1, -2], d2_209 = [1, -3, 4];
Q('s209', mk.short({ marks: 2, stem: r`The diagonals of a parallelogram-shaped flower bed are $${vt(d1_209)}$ and $${vt(d2_209)}$ (in metres). Find the area of the bed.`, model: r`Area $= \tfrac12 |\vec{d_1} \times \vec{d_2}|$.\n\n$\vec{d_1} \times \vec{d_2} = (4 - 6)\hat{i} - (12 + 2)\hat{j} + (-9 - 1)\hat{k} = -2\hat{i} - 14\hat{j} - 10\hat{k}$, of magnitude $\sqrt{4 + 196 + 100} = \sqrt{300} = 10\sqrt{3}$.\n\nArea $= 5\sqrt{3}$ m².`, sol: 'With diagonals, the area is half the magnitude of their cross product.', scheme: [['Cross product of the diagonals', 1], ['Area 5√3', 1]], d: 3, c: 'application', t: [5], time: 120 }), (C) => { const c = cross(d1_209, d2_209); C.assert(eqV(c, [-2, -14, -10]), 'cross'); const a = add(d1_209, d2_209).map((x) => x / 2), b = sub(d1_209, d2_209).map((x) => x / 2); C.assert(near(mag(cross(a, b)), 5 * s3) && near(mag(c) / 2, 5 * s3), 'area from sides equals half |d1 x d2|'); C.model([r`5\sqrt{3}`]); });

// =============================================================== short answer, 3 marks
const A301 = [1, 0, 2], B301 = [3, 1, 0], C301 = [4, 1, 1];
Q('s301', mk.short({ marks: 3, stem: r`Three survey stakes are at $A${pt(A301)}$, $B${pt(B301)}$ and $C${pt(C301)}$. Using vectors, show that they form a right-angled triangle, and name the right angle.`, model: r`$\overrightarrow{AB} = 2\hat{i} + \hat{j} - 2\hat{k}$, $\overrightarrow{BC} = \hat{i} + \hat{k}$, $\overrightarrow{AC} = 3\hat{i} + \hat{j} - \hat{k}$.\n\n$\overrightarrow{AB} \cdot \overrightarrow{BC} = 2 + 0 - 2 = 0$, so $AB \perp BC$.\n\nThe points are not collinear ($\overrightarrow{AC}$ is not a multiple of $\overrightarrow{AB}$), so $ABC$ is a triangle with the right angle at $B$. Check: $|AB|^2 + |BC|^2 = 9 + 2 = 11 = |AC|^2$.`, sol: 'Find the side vectors and look for a zero dot product.', scheme: [['Side vectors', 1], ['Zero dot product', 1], ['Right angle at B (with a check)', 1]], d: 3, c: 'application', t: [2, 4], time: 150 }), (C) => { const AB = sub(B301, A301), BC = sub(C301, B301), AC = sub(C301, A301); C.assert(near(dot(AB, BC), 0) && !collinear(AB, AC) && near(dot(AB, AB) + dot(BC, BC), dot(AC, AC)), 'right angle at B'); C.model([vt(AB), vt(BC), 11]); });
const s302dr = [2, 3, -6];
Q('s302', mk.short({ marks: 3, stem: r`A rope of length $14$ m is stretched along a direction whose direction ratios are $2, 3, -6$. Find the vector(s) representing the rope and its direction cosines.`, model: r`A vector along the direction is $2\hat{i} + 3\hat{j} - 6\hat{k}$, of magnitude $\sqrt{4 + 9 + 36} = 7$.\n\nDirection cosines: $\pm\left(\tfrac27, \tfrac37, -\tfrac67\right)$.\n\nThe rope vector is $14 \times \tfrac17(2\hat{i} + 3\hat{j} - 6\hat{k}) = 4\hat{i} + 6\hat{j} - 12\hat{k}$, or its negative $-4\hat{i} - 6\hat{j} + 12\hat{k}$ for the opposite sense.`, sol: 'Normalise the direction ratios, then scale to length 14.', scheme: [['Magnitude 7 of the direction', 1], ['Direction cosines', 1], ['Vector 4i + 6j − 12k (or its negative)', 1]], d: 2, c: 'application', t: [1], time: 150 }), (C) => { const v = scl(14, unit(s302dr)); C.assert(eqV(v, [4, 6, -12]) && near(mag(v), 14), 'rope vector'); C.model([vt([4, 6, -12])]); });
Q('s303', mk.short({ marks: 3, stem: r`Find $x$ and $y$ if the vectors $(x + y)\hat{i} + (2x - y)\hat{j} + 3\hat{k}$ and $5\hat{i} + 4\hat{j} + 3\hat{k}$ record the same displacement of a parcel, and then find the magnitude of that displacement.`, model: r`Equal vectors have equal components: $x + y = 5$ and $2x - y = 4$.\n\nAdding, $3x = 9$, so $x = 3$ and $y = 2$.\n\nThe displacement is $5\hat{i} + 4\hat{j} + 3\hat{k}$, of magnitude $\sqrt{25 + 16 + 9} = \sqrt{50} = 5\sqrt{2}$.`, sol: 'Equate components, solve, then find the magnitude.', scheme: [['Equations from equal components', 1], ['x = 3, y = 2', 1], ['Magnitude 5√2', 1]], d: 2, c: 'understanding', t: [1, 2], time: 150 }), (C) => { const x = 3, y = 2; C.assert(eqV([x + y, 2 * x - y, 3], [5, 4, 3]) && near(mag([5, 4, 3]), 5 * s2), 'x, y'); C.model(['x = 3', 'y = 2', r`5\sqrt{2}`]); });
const A304 = [1, 2, -3], B304 = [4, -1, 3];
Q('s304', mk.short({ marks: 3, stem: r`A highway runs straight through towns $A${pt(A304)}$ and $B${pt(B304)}$. A fuel station $R$ divides $AB$ internally in the ratio $2 : 1$, and a toll plaza $S$ divides $AB$ externally in the ratio $2 : 1$. Find the position vectors of $R$ and $S$, and the ratio in which $B$ divides $RS$.`, model: r`$\vec{r} = \dfrac{2\vec{b} + \vec{a}}{3} = \dfrac{(8 + 1)\hat{i} + (-2 + 2)\hat{j} + (6 - 3)\hat{k}}{3} = 3\hat{i} + \hat{k}$.\n\n$\vec{s} = \dfrac{2\vec{b} - \vec{a}}{2 - 1} = 7\hat{i} - 4\hat{j} + 9\hat{k}$.\n\n$\overrightarrow{RB} = \hat{i} - \hat{j} + 2\hat{k}$ and $\overrightarrow{BS} = 3\hat{i} - 3\hat{j} + 6\hat{k} = 3\,\overrightarrow{RB}$, so $B$ divides $RS$ internally in the ratio $1 : 3$.`, sol: 'Use both section formulae, then compare RB and BS.', scheme: [['R', 1], ['S', 1], ['B divides RS in 1 : 3', 1]], d: 4, c: 'analysis', t: [3], time: 180 }), (C) => { const R = sectionIn(A304, B304, 2, 1), S = sectionEx(A304, B304, 2, 1); C.assert(eqV(R, [3, 0, 1]) && eqV(S, [7, -4, 9]) && eqV(sectionIn(R, S, 1, 3), B304), 'R, S and B in 1 : 3'); C.model([vt(R), vt(S), '1 : 3']); });
const A305 = [2, 3, -4], B305 = [1, -2, 3], C305 = [4, 13, -18];
Q('s305', mk.short({ marks: 3, stem: r`Three lamp posts on a straight promenade are planned at $A${pt(A305)}$, $B${pt(B305)}$ and $C${pt(C305)}$. Show that they are collinear and find the ratio in which $A$ divides $BC$.`, model: r`$\overrightarrow{BA} = \hat{i} + 5\hat{j} - 7\hat{k}$ and $\overrightarrow{AC} = 2\hat{i} + 10\hat{j} - 14\hat{k} = 2\,\overrightarrow{BA}$.\n\nSo $\overrightarrow{BA}$ and $\overrightarrow{AC}$ are parallel and share the point $A$: $B$, $A$, $C$ are collinear.\n\nSince $\overrightarrow{AC} = 2\,\overrightarrow{BA}$ in the same direction, $A$ lies between $B$ and $C$ with $BA : AC = 1 : 2$.`, sol: 'Show one segment vector is a multiple of the other and read the ratio.', scheme: [['Segment vectors', 1], ['Parallel with a common point, so collinear', 1], ['Ratio 1 : 2', 1]], d: 3, c: 'application', t: [3, 5], time: 150 }), (C) => { const BA = sub(A305, B305), AC = sub(C305, A305); C.assert(eqV(AC, scl(2, BA)) && collinear(BA, AC) && eqV(sectionIn(B305, C305, 1, 2), A305), 'collinear, 1 : 2'); C.model(['1 : 2']); });
Q('s306', mk.short({ marks: 3, stem: r`Three forces in a tug-of-war knot balance, so $\vec{a} + \vec{b} + \vec{c} = \vec{0}$, with magnitudes $|\vec{a}| = 5$, $|\vec{b}| = 8$ and $|\vec{c}| = 7$. Find the angle between $\vec{a}$ and $\vec{b}$.`, model: r`$\vec{c} = -(\vec{a} + \vec{b})$, so $|\vec{c}|^2 = |\vec{a}|^2 + |\vec{b}|^2 + 2\,\vec{a} \cdot \vec{b}$.\n\n$49 = 25 + 64 + 2\,\vec{a} \cdot \vec{b}$, so $\vec{a} \cdot \vec{b} = -20$.\n\n$\cos\theta = \dfrac{-20}{5 \times 8} = -\dfrac12$, so $\theta = 120^\circ$ $\left(\dfrac{2\pi}{3}\right)$.`, sol: 'Square c = −(a + b) to find a · b.', scheme: [['|c|² expanded', 1], ['a · b = −20', 1], ['θ = 120°', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { const th = (2 * Math.PI) / 3, a = [5, 0, 0], b = [8 * Math.cos(th), 8 * Math.sin(th), 0], c = scl(-1, add(a, b)); C.assert(near(mag(c), 7) && near(dot(a, b), -20), 'consistent'); C.model([-20, 120]); });
const a307 = [4, 1, -3], b307 = [2, -2, 1];
Q('s307', mk.short({ marks: 3, stem: r`A crane's load moves along $\vec{a} = ${vt(a307)}$ while the jib points along $\vec{b} = ${vt(b307)}$. Find the scalar and vector projections of $\vec{a}$ on $\vec{b}$.`, model: r`$\vec{a} \cdot \vec{b} = 8 - 2 - 3 = 3$ and $|\vec{b}| = \sqrt{4 + 4 + 1} = 3$.\n\nScalar projection $= \dfrac{3}{3} = 1$.\n\nVector projection $= \dfrac{\vec{a} \cdot \vec{b}}{|\vec{b}|^2}\,\vec{b} = \dfrac39\,\vec{b} = \tfrac13(2\hat{i} - 2\hat{j} + \hat{k})$.`, sol: 'Scalar: a · b / |b|; vector: (a · b / |b|²) b.', scheme: [['a · b and |b|', 1], ['Scalar projection 1', 1], ['Vector projection', 1]], d: 2, c: 'application', t: [4], time: 150 }), (C) => { C.assert(near(proj(a307, b307), 1) && eqV(scl(dot(a307, b307) / dot(b307, b307), b307), scl(1 / 3, b307)), 'projections'); C.model([1, r`\tfrac13(2\hat{i} - 2\hat{j} + \hat{k})`]); });
const a308 = [2, 1, -1], b308 = [1, -1, 2];
Q('s308', mk.short({ marks: 3, stem: r`A satellite dish must face at right angles to two support rods along $\vec{a} = ${vt(a308)}$ and $\vec{b} = ${vt(b308)}$. Find a unit vector perpendicular to both rods.`, model: r`$\vec{a} \times \vec{b} = \begin{vmatrix} \hat{i} & \hat{j} & \hat{k} \\ 2 & 1 & -1 \\ 1 & -1 & 2 \end{vmatrix} = (2 - 1)\hat{i} - (4 + 1)\hat{j} + (-2 - 1)\hat{k} = \hat{i} - 5\hat{j} - 3\hat{k}$.\n\n$|\vec{a} \times \vec{b}| = \sqrt{1 + 25 + 9} = \sqrt{35}$.\n\nUnit vectors: $\pm\dfrac{1}{\sqrt{35}}(\hat{i} - 5\hat{j} - 3\hat{k})$.`, sol: 'Cross product, then divide by its magnitude; both signs work.', scheme: [['Cross product', 1], ['Magnitude √35', 1], ['Unit vector(s)', 1]], d: 2, c: 'application', t: [5], time: 150 }), (C) => { const c = cross(a308, b308); C.assert(eqV(c, [1, -5, -3]) && near(mag(c), Math.sqrt(35)) && near(dot(c, a308), 0) && near(dot(c, b308), 0), 'perpendicular'); C.model([vt(c), r`\sqrt{35}`]); });
const A309 = [2, 1, 1], B309 = [3, -1, 4], C309 = [1, 2, 0];
Q('s309', mk.short({ marks: 3, stem: r`A gardener ropes off a triangular herb patch with corners $A${pt(A309)}$, $B${pt(B309)}$ and $C${pt(C309)}$. Find the area of the patch.`, model: r`$\overrightarrow{AB} = \hat{i} - 2\hat{j} + 3\hat{k}$ and $\overrightarrow{AC} = -\hat{i} + \hat{j} - \hat{k}$.\n\n$\overrightarrow{AB} \times \overrightarrow{AC} = (2 - 3)\hat{i} - (-1 + 3)\hat{j} + (1 - 2)\hat{k} = -\hat{i} - 2\hat{j} - \hat{k}$, of magnitude $\sqrt{6}$.\n\nArea $= \dfrac{\sqrt{6}}{2}$ square units.`, sol: 'Half the magnitude of the cross product of two side vectors.', scheme: [['Side vectors', 1], ['Cross product', 1], ['Area √6/2', 1]], d: 2, c: 'application', t: [5], time: 150 }), (C) => { C.assert(eqV(cross(sub(B309, A309), sub(C309, A309)), [-1, -2, -1]) && near(triArea(A309, B309, C309), Math.sqrt(6) / 2), 'area'); C.model([r`\dfrac{\sqrt{6}}{2}`]); });
const a310 = [1, 2, -2], b310 = [3, 0, 4];
Q('s310', mk.short({ marks: 3, stem: r`For the vectors $\vec{a} = ${vt(a310)}$ and $\vec{b} = ${vt(b310)}$ used in a navigation exercise, verify that $|\vec{a} \times \vec{b}|^2 + (\vec{a} \cdot \vec{b})^2 = |\vec{a}|^2 |\vec{b}|^2$.`, model: r`$\vec{a} \cdot \vec{b} = 3 + 0 - 8 = -5$.\n\n$\vec{a} \times \vec{b} = (8 - 0)\hat{i} - (4 + 6)\hat{j} + (0 - 6)\hat{k} = 8\hat{i} - 10\hat{j} - 6\hat{k}$, so $|\vec{a} \times \vec{b}|^2 = 64 + 100 + 36 = 200$.\n\nLeft side $= 200 + 25 = 225$; right side $= |\vec{a}|^2 |\vec{b}|^2 = 9 \times 25 = 225$. Verified.`, sol: 'Compute both products and both magnitudes, then compare.', scheme: [['a · b = −5', 1], ['|a × b|² = 200', 1], ['Both sides 225', 1]], d: 3, c: 'analysis', t: [4, 5], time: 150 }), (C) => { const c = cross(a310, b310); C.assert(eqV(c, [8, -10, -6]) && near(dot(c, c) + dot(a310, b310) ** 2, dot(a310, a310) * dot(b310, b310)), 'identity'); C.model([200, 225]); });

// =============================================================== long answer, 5 marks (in parts)
const Aw = [2, -1, 2], ABw = [4, 4, -2], Bw = add(Aw, ABw);
Q('l01', mk.long({ stem: r`A drone takes off from the origin $O$ to a hover point $A${pt(Aw)}$ and then flies the leg $\overrightarrow{AB} = ${vt(ABw)}$ (in hundreds of metres).\n\n(a) Find the position vector of $B$, the distance $OB$, and the direction cosines of $\overrightarrow{OB}$. [3]\n\n(b) Find the unit vector along $\overrightarrow{AB}$ and the vector of magnitude $10$ along $\overrightarrow{AB}$. [2]`, model: r`**(a)** $\vec{b} = \vec{a} + \overrightarrow{AB} = (2 + 4)\hat{i} + (-1 + 4)\hat{j} + (2 - 2)\hat{k} = 6\hat{i} + 3\hat{j}$.\n\n$OB = \sqrt{36 + 9} = \sqrt{45} = 3\sqrt{5}$ (hundred metres).\n\nDirection cosines of $\overrightarrow{OB}$: $\dfrac{6}{3\sqrt{5}}, \dfrac{3}{3\sqrt{5}}, 0 = \dfrac{2}{\sqrt{5}}, \dfrac{1}{\sqrt{5}}, 0$.\n\n**(b)** $|\overrightarrow{AB}| = \sqrt{16 + 16 + 4} = 6$, so the unit vector is $\tfrac16(4\hat{i} + 4\hat{j} - 2\hat{k}) = \tfrac13(2\hat{i} + 2\hat{j} - \hat{k})$.\n\nThe vector of magnitude $10$ is $\tfrac{10}{3}(2\hat{i} + 2\hat{j} - \hat{k})$.`, sol: 'Add the vectors for B, then normalise each direction.', scheme: [['Position vector of B', 1], ['OB = 3√5', 1], ['Direction cosines of OB', 1], ['Unit vector along AB', 1], ['Vector of magnitude 10', 1]], d: 3, c: 'application', t: [1, 2], time: 480 }), (C) => { C.assert(eqV(Bw, [6, 3, 0]) && near(mag(Bw), 3 * Math.sqrt(5)) && eqV(unit(Bw), [2 / Math.sqrt(5), 1 / Math.sqrt(5), 0]), 'B'); C.assert(eqV(unit(ABw), scl(1 / 3, [2, 2, -1])) && near(mag(scl(10, unit(ABw))), 10), 'AB'); C.model([vt(Bw), r`3\sqrt{5}`, r`\tfrac{10}{3}(2\hat{i} + 2\hat{j} - \hat{k})`]); });
const Al2 = [2, -3, 4], Bl2 = [8, 0, -2];
const Pl2 = sectionIn(Al2, Bl2, 1, 2), Ql2 = sectionEx(Al2, Bl2, 1, 2);
Q('l02', mk.long({ stem: r`A metro line is planned straight through stations $A${pt(Al2)}$ and $B${pt(Bl2)}$.\n\n(a) Find the station $P$ that divides $AB$ internally in the ratio $1 : 2$ and the depot $Q$ that divides $AB$ externally in the ratio $1 : 2$. [3]\n\n(b) Show that $Q$, $A$ and $P$ are collinear and find the ratio in which $A$ divides $QP$. [2]`, model: r`**(a)** $\vec{p} = \dfrac{1 \cdot \vec{b} + 2\vec{a}}{3} = \dfrac{(8 + 4)\hat{i} + (0 - 6)\hat{j} + (-2 + 8)\hat{k}}{3} = 4\hat{i} - 2\hat{j} + 2\hat{k}$, so $P = (4, -2, 2)$.\n\n$\vec{q} = \dfrac{1 \cdot \vec{b} - 2\vec{a}}{1 - 2} = 2\vec{a} - \vec{b} = -4\hat{i} - 6\hat{j} + 10\hat{k}$, so $Q = (-4, -6, 10)$.\n\n**(b)** $\overrightarrow{QA} = 6\hat{i} + 3\hat{j} - 6\hat{k}$ and $\overrightarrow{AP} = 2\hat{i} + \hat{j} - 2\hat{k}$, so $\overrightarrow{QA} = 3\,\overrightarrow{AP}$.\n\nThe vectors are parallel with the common point $A$, so $Q$, $A$, $P$ are collinear, and $A$ divides $QP$ internally in the ratio $3 : 1$.`, sol: 'Internal and external section formulae, then compare QA with AP.', scheme: [['P', 1], ['Q', 1], ['Correct use of m − n for external division', 1], ['QA = 3 AP, collinear', 1], ['Ratio 3 : 1', 1]], d: 4, c: 'analysis', t: [3], time: 480 }), (C) => { C.assert(eqV(Pl2, [4, -2, 2]) && eqV(Ql2, [-4, -6, 10]), 'P, Q'); C.assert(eqV(sub(Al2, Ql2), scl(3, sub(Pl2, Al2))) && eqV(sectionIn(Ql2, Pl2, 3, 1), Al2), 'A divides QP in 3 : 1'); C.model([vt(Pl2), vt(Ql2), '3 : 1']); });
const al3 = [3, -6, 2], bl3 = [2, 1, -2];
Q('l03', mk.long({ stem: r`In a robotics lab, a gripper moves along $\vec{a} = ${vt(al3)}$ and a conveyor belt runs along $\vec{b} = ${vt(bl3)}$.\n\n(a) Find the angle between $\vec{a}$ and $\vec{b}$, leaving your answer as an inverse cosine. [2]\n\n(b) Find the scalar projection of $\vec{a}$ on $\vec{b}$, and the value of $\lambda$ for which $\vec{a} + \lambda\vec{b}$ is perpendicular to $\vec{b}$. [3]`, model: r`**(a)** $\vec{a} \cdot \vec{b} = 6 - 6 - 4 = -4$, $|\vec{a}| = \sqrt{9 + 36 + 4} = 7$, $|\vec{b}| = 3$.\n\n$\cos\theta = \dfrac{-4}{21}$, so $\theta = \cos^{-1}\left(-\dfrac{4}{21}\right)$, an obtuse angle.\n\n**(b)** Scalar projection $= \dfrac{\vec{a} \cdot \vec{b}}{|\vec{b}|} = -\dfrac43$.\n\n$(\vec{a} + \lambda\vec{b}) \cdot \vec{b} = \vec{a} \cdot \vec{b} + \lambda|\vec{b}|^2 = -4 + 9\lambda = 0$, so $\lambda = \dfrac49$.`, sol: 'Dot product and magnitudes; then set (a + λb) · b = 0.', scheme: [['a · b, |a|, |b|', 1], ['Angle', 1], ['Scalar projection −4/3', 1], ['Equation in λ', 1], ['λ = 4/9', 1]], d: 3, c: 'application', t: [4], time: 480 }), (C) => { C.assert(near(cosAngle(al3, bl3), -4 / 21) && near(proj(al3, bl3), -4 / 3) && near(dot(add(al3, scl(4 / 9, bl3)), bl3), 0), 'angle, projection, lambda'); C.model([r`-\dfrac{4}{21}`, r`-\dfrac43`, r`\dfrac49`]); });
const Al4 = [1, 1, 2], Bl4 = [2, 3, 5], Cl4 = [1, 5, 5];
const Nl4 = cross(sub(Bl4, Al4), sub(Cl4, Al4));
Q('l04', mk.long({ stem: r`A triangular roof panel has corners $A${pt(Al4)}$, $B${pt(Bl4)}$ and $C${pt(Cl4)}$ (in metres).\n\n(a) Find the area of the panel. [3]\n\n(b) Find a unit vector perpendicular to the panel, and the length of the perpendicular from $A$ to the edge $BC$. [2]`, model: r`**(a)** $\overrightarrow{AB} = \hat{i} + 2\hat{j} + 3\hat{k}$ and $\overrightarrow{AC} = 4\hat{j} + 3\hat{k}$.\n\n$\overrightarrow{AB} \times \overrightarrow{AC} = (6 - 12)\hat{i} - (3 - 0)\hat{j} + (4 - 0)\hat{k} = -6\hat{i} - 3\hat{j} + 4\hat{k}$, of magnitude $\sqrt{36 + 9 + 16} = \sqrt{61}$.\n\nArea $= \dfrac{\sqrt{61}}{2}$ m².\n\n**(b)** Unit normal: $\pm\dfrac{1}{\sqrt{61}}(-6\hat{i} - 3\hat{j} + 4\hat{k})$.\n\n$|\overrightarrow{BC}| = |-\hat{i} + 2\hat{j}| = \sqrt{5}$. Area $= \tfrac12 \times BC \times h$, so $h = \dfrac{2 \times \tfrac{\sqrt{61}}{2}}{\sqrt{5}} = \sqrt{\dfrac{61}{5}}$ m.`, sol: 'Cross product of two edges for the area and the normal; then area = ½ × base × height.', scheme: [['Edge vectors', 1], ['Cross product', 1], ['Area √61/2', 1], ['Unit normal', 1], ['Height √(61/5)', 1]], d: 4, c: 'analysis', t: [5], time: 480 }), (C) => { C.assert(eqV(Nl4, [-6, -3, 4]) && near(triArea(Al4, Bl4, Cl4), Math.sqrt(61) / 2), 'area'); const BC = sub(Cl4, Bl4), t = dot(sub(Al4, Bl4), BC) / dot(BC, BC), foot = add(Bl4, scl(t, BC)); C.assert(near(mag(sub(Al4, foot)), Math.sqrt(61 / 5)), 'height by foot of perpendicular'); C.model([vt(Nl4), r`\sqrt{61}`, r`\sqrt{\dfrac{61}{5}}`]); });
const Al5 = [1, 0, 1], Bl5 = [3, 2, 1], Cl5 = [2, 1, 4];
const ABl5 = sub(Bl5, Al5), ACl5 = sub(Cl5, Al5), Fl5 = add(Al5, scl(dot(ACl5, ABl5) / dot(ABl5, ABl5), ABl5));
Q('l05', mk.long({ stem: r`Three beacons on a hill are at $A${pt(Al5)}$, $B${pt(Bl5)}$ and $C${pt(Cl5)}$.\n\n(a) Find $|\overrightarrow{AB}|$, $|\overrightarrow{AC}|$ and the cosine of the angle $BAC$. [3]\n\n(b) Find the scalar projection of $\overrightarrow{AC}$ on $\overrightarrow{AB}$, and the foot $F$ of the perpendicular from $C$ to the line $AB$. [2]`, model: r`**(a)** $\overrightarrow{AB} = 2\hat{i} + 2\hat{j}$, $\overrightarrow{AC} = \hat{i} + \hat{j} + 3\hat{k}$; $|\overrightarrow{AB}| = 2\sqrt{2}$, $|\overrightarrow{AC}| = \sqrt{11}$.\n\n$\overrightarrow{AB} \cdot \overrightarrow{AC} = 2 + 2 + 0 = 4$, so $\cos A = \dfrac{4}{2\sqrt{2}\sqrt{11}} = \dfrac{2}{\sqrt{22}}$.\n\n**(b)** Projection of $\overrightarrow{AC}$ on $\overrightarrow{AB}$ $= \dfrac{4}{2\sqrt{2}} = \sqrt{2}$.\n\n$\overrightarrow{AF} = \dfrac{4}{8}\,\overrightarrow{AB} = \hat{i} + \hat{j}$, so $F = (2, 1, 1)$. Check: $\overrightarrow{FC} = 3\hat{k}$ and $\overrightarrow{FC} \cdot \overrightarrow{AB} = 0$.`, sol: 'Dot product for the angle; vector projection for the foot of the perpendicular.', scheme: [['|AB| and |AC|', 1], ['AB · AC = 4', 1], ['cos A', 1], ['Projection √2', 1], ['F = (2, 1, 1) with check', 1]], d: 4, c: 'analysis', t: [4], time: 480 }), (C) => { C.assert(near(cosAngle(ABl5, ACl5), 2 / Math.sqrt(22)) && near(proj(ACl5, ABl5), s2) && eqV(Fl5, [2, 1, 1]) && near(dot(sub(Cl5, Fl5), ABl5), 0), 'angle, projection, foot'); C.model([r`\dfrac{2}{\sqrt{22}}`, r`\sqrt{2}`, '(2, 1, 1)']); });
const al6 = [2, -1, 3], bl6 = [-4, 2, -6], cl6 = [1, 5, 1];
Q('l06', mk.long({ stem: r`In a 3-D modelling app, $\vec{a} = ${vt(al6)}$, $\vec{b} = ${vt(bl6)}$ and $\vec{c} = ${vt(cl6)}$.\n\n(a) Show that $\vec{a}$ and $\vec{b}$ are collinear and that $\vec{c}$ is perpendicular to $\vec{a}$. [2]\n\n(b) Find the area of the parallelogram with adjacent sides $\vec{a}$ and $\vec{c}$, and check it using $|\vec{a}||\vec{c}|$. [3]`, model: r`**(a)** $\vec{b} = -2\vec{a}$, so $\vec{a}$ and $\vec{b}$ are collinear (opposite in direction). $\vec{a} \cdot \vec{c} = 2 - 5 + 3 = 0$, so $\vec{c} \perp \vec{a}$.\n\n**(b)** $\vec{a} \times \vec{c} = (-1 - 15)\hat{i} - (2 - 3)\hat{j} + (10 + 1)\hat{k} = -16\hat{i} + \hat{j} + 11\hat{k}$.\n\nArea $= \sqrt{256 + 1 + 121} = \sqrt{378} = 3\sqrt{42}$ square units.\n\nCheck: since $\vec{a} \perp \vec{c}$, $\sin\theta = 1$ and the area is $|\vec{a}||\vec{c}| = \sqrt{14}\sqrt{27} = \sqrt{378}$.`, sol: 'A multiple shows collinearity; a zero dot product shows perpendicularity; the cross product gives the area.', scheme: [['b = −2a, collinear', 1], ['a · c = 0', 1], ['a × c', 1], ['Area 3√42', 1], ['Check with |a||c|', 1]], d: 3, c: 'application', t: [1, 4, 5], time: 480 }), (C) => { const x = cross(al6, cl6); C.assert(eqV(bl6, scl(-2, al6)) && near(dot(al6, cl6), 0) && eqV(x, [-16, 1, 11]) && near(mag(x), 3 * Math.sqrt(42)) && near(mag(al6) * mag(cl6), Math.sqrt(378)), 'collinear, perpendicular, area'); C.model([vt(x), r`3\sqrt{42}`]); });
